// Some portions generated by Claude
/** Which edge a pointer is on: the canvas hit-tests the curves itself instead of adding wide invisible paths. */
import type { EdgeCurve, PointerPosition } from "./graph-types.ts";

const SAMPLES = 24;

function pointAt(curve: EdgeCurve, t: number): PointerPosition {
  const u = 1 - t;
  return {
    x: u * u * curve.start.x + 2 * u * t * curve.control.x + t * t * curve.end.x,
    y: u * u * curve.start.y + 2 * u * t * curve.control.y + t * t * curve.end.y,
  };
}

function segmentDistance(point: PointerPosition, from: PointerPosition, to: PointerPosition) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = dx * dx + dy * dy;
  const t = length ? Math.max(0, Math.min(1, ((point.x - from.x) * dx + (point.y - from.y) * dy) / length)) : 0;
  return Math.hypot(point.x - (from.x + t * dx), point.y - (from.y + t * dy));
}

/** The edge whose curve passes closest to the point, if it is within `tolerance` (graph units); null otherwise. */
export function nearestEdge(point: PointerPosition, curves: ReadonlyMap<string, EdgeCurve>, tolerance: number) {
  let best: string | null = null;
  let bestDistance = tolerance;
  for (const [id, curve] of curves) {
    const { start, control, end } = curve;
    if (
      point.x < Math.min(start.x, control.x, end.x) - tolerance ||
      point.x > Math.max(start.x, control.x, end.x) + tolerance ||
      point.y < Math.min(start.y, control.y, end.y) - tolerance ||
      point.y > Math.max(start.y, control.y, end.y) + tolerance
    )
      continue;
    let previous = start;
    for (let index = 1; index <= SAMPLES; index += 1) {
      const next = pointAt(curve, index / SAMPLES);
      const distance = segmentDistance(point, previous, next);
      if (distance <= bestDistance) {
        bestDistance = distance;
        best = id;
      }
      previous = next;
    }
  }
  return best;
}

/** The middle of a curve. */
export function curveMidpoint(curve: EdgeCurve): PointerPosition {
  return pointAt(curve, 0.5);
}
